def solve_cached(M_bytes, n):
    M = np.frombuffer(M_bytes, dtype=np.float64).reshape((n, n))
    a = np.ones(n, dtype=np.float64) / n
    b = np.ones(n, dtype=np.float64) / n
    return ot.lp.emd(a, b, M, check_marginals=False)

